-- River Fishing Challenge: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'river_fishing', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["fish-01",1,"Bình Minh Trên Hồ Ngọc","Video đứng trên thuyền nhôm câu cá giữa hồ xanh ngọc, nước trong nhìn thấy đáy; file mục II.2.","Sáng sớm, bác Năm ngư dân dẫn cả lớp ra bến gỗ, chia mỗi nhóm một thuyền nhôm nhỏ và một cây cần gỗ cũ. Bác kể rằng hồ Ngọc có sáu loài cá thường gặp và một truyền thuyết: Cá Hồi Hoàng Gia chỉ ngoi lên khi mặt trời vừa ló khỏi đỉnh núi. Các thuyền phải học cách quăng cần, chờ phao chìm và giữ thanh căng dây, rồi điền vào Sổ Câu Cá đủ các loài cá của hồ. Câu đúng giúp nâng cần, đổi mồi, và cá lớn sẽ tìm đến. Khi ánh nắng đầu tiên chạm mặt hồ, thuyền nào có cần vàng sẽ có cơ hội gặp Cá Hồi Hoàng Gia.","Hồ xanh ngọc dưới chân núi lúc bình minh, sương mỏng trên mặt nước, rừng thông soi bóng. Mặt hồ phẳng lặng, nhìn thấy đá cuội và đàn cá nhỏ dưới đáy. Bên cạnh thuyền nhôm là một chiếc thuyền chèo trắng có lưới vàng và phao cứu sinh treo cạnh bến.",[{"n":1,"title":"Ra bến, lên thuyền","minutes":5,"optional":false,"goal":"Nhận thuyền, áo phao, cần gỗ; chèo ra giữa hồ.","beats":["Bác Năm dạy 3 bước: quăng, chờ, kéo.","Mỗi câu đúng là một nhịp chèo ra vị trí neo.","Bác Năm chỉ chiếc thuyền chèo cũ của ông: mỗi món trên thuyền đọc đúng tên được một mồi giun.","Cần câu gỗ cấp một của bác Năm: cầm đúng tay mới quăng được.","Giá gác cần và ghế gấp trên thuyền: gọi đúng tên đồ nghề để ngồi vào chỗ."],"question_hook":"Câu hỏi trên mái chèo; câu đúng đưa thuyền ra khu cá nhiều hơn.","reward":"Cần gỗ + mồi giun.","vocab":["boat","paddle","life jacket","rod","rowboat","net","lifebuoy","wooden rod","beginner","rod holder","boat chair"],"assets":["river_dock","river_boat_aluminium","kayak_lifejacket","fish_rod","fish_bait","hdri_dawn","river_boat_row","river_buoy","fish_rod_wood","fish_rod_holder","fish_boat_chair"],"subtitles":[{"en":"Get in the boat, put on your life jacket and take your rod.","vi":"Xuống thuyền, mặc áo phao và nhận cần câu.","parts":["Xuống ",["boat","thuyền",0],", mặc áo ",["life jacket","phao",3]," và nhận ",["rod","cần câu",1],"."]},{"en":"Paddle out to the middle of the lake at dawn.","vi":"Chèo ra giữa hồ lúc bình minh.","parts":[["Paddle","Chèo",1]," ra giữa hồ lúc bình minh."]}]},{"n":2,"title":"Cú quăng đầu tiên","minutes":5,"optional":false,"goal":"Học quăng cần bằng Thanh lực quăng, bắt con cá đầu tiên.","beats":["Thanh lực quăng: dừng đúng vùng xanh để phao rơi xa.","Cá rô phi và cá rô đồng cắn câu nhiều.","Bác Năm đứng yên chờ cá cắn trong tư thế câu chờ: nhìn tư thế rồi đọc đúng tên từng động tác."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cá đầu tiên vào Sổ Câu Cá.","vocab":["cast","float","bite","pull","bobber","wait"],"assets":["fish_bobber","fish_reel","fish_hook","fish_tilapia","fish_climbing_perch","anim_cast","anim_fishing_idle"],"subtitles":[{"en":"Cast the rod far and watch the float.","vi":"Quăng cần thật xa, nhìn phao nổi.","parts":[["Cast","Quăng",2]," cần thật xa, nhìn ",["float","phao",2]," nổi."]},{"en":"The float sinks: a fish bites! Pull the rod up!","vi":"Phao chìm: có cá cắn! Kéo cần lên!","parts":["Phao chìm: có cá ",["bite","cắn",2],"! ",["Pull","Kéo",1]," cần lên!"]}]},{"n":3,"title":"Đổi mồi, đổi chỗ","minutes":5,"optional":false,"goal":"Thử mồi tôm và mồi cá nhỏ để bắt cá chép, cá diếc.","beats":["Mồi khác nhau gọi loài khác nhau.","Sau 3 câu đúng: nâng cần sợi thủy tinh."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cần sợi thủy tinh.","vocab":["bait","worm","shrimp","change"],"assets":["fish_bait","fish_carp","fish_crucian","fish_tackle_box"],"subtitles":[{"en":"Try worm bait or shrimp bait?","vi":"Thử mồi giun hay mồi tôm?","parts":["Thử mồi ",["worm","giun",2]," hay mồi ",["shrimp","tôm",2],"?"]},{"en":"Which bait do carp like more? Try changing it!","vi":"Mồi nào cá chép thích hơn? Hãy đổi thử!","parts":[["Bait","Mồi",2]," nào cá chép thích hơn? Hãy ",["change","đổi",2]," thử!"]}]},{"n":4,"title":"Khúc sâu gần bãi đá","minutes":5,"optional":false,"goal":"Neo thuyền gần bãi đá, săn cá trắm và cá lóc.","beats":["Cá lớn kéo mạnh, thanh căng dây rung nhiều.","Vợt cần người thứ hai trên thuyền trả lời đúng."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Cá to cần 2 câu đúng liên tiếp.","reward":"Vợt + cần carbon.","vocab":["deep","strong","net","heavy"],"assets":["fish_grass_carp","fish_snakehead","fish_net","river_rock_large"],"subtitles":[{"en":"The deep spot near the rocks has strong grass carp.","vi":"Khúc sâu gần bãi đá có cá trắm khỏe.","parts":["Khúc ",["deep","sâu",1]," gần bãi đá có cá trắm ",["strong","khỏe",1],"."]},{"en":"The fish is heavy, so use the net; it is really heavy.","vi":"Cá nặng, dùng vợt giúp em, nó thật nặng.","parts":["Cá nặng, dùng ",["net","vợt",1]," giúp em, nó thật ",["heavy","nặng",2],"."]}]},{"n":5,"title":"Cân và ghi kỷ lục","minutes":5,"optional":false,"goal":"Về bến cân cá, ghi Sổ Câu Cá, thả cá lại hồ.","beats":["Bảng kỷ lục xếp hạng theo điểm.","Câu đúng mở khóa \"sự thật về loài cá\".","Cá được bỏ vào giỏ đan trước khi cân.","Cá tuyết nhỏ nằm trong thùng cá trước khi cân: đọc tên cá trên nhãn thùng."],"question_hook":"Câu hỏi hiện trên bảng cân; đúng thì cân chính xác và cộng điểm thưởng.","reward":"Cần vàng cho 3 thuyền dẫn đầu và mọi em đủ 9 câu đúng.","vocab":["weigh","record","release","kilogram","basket","cod","fish box"],"assets":["fish_scale","fish_record_board","fish_bucket","river_dock","fish_basket","fish_cod","fish_box"],"subtitles":[{"en":"Back at the dock, how many kilograms does the fish weigh?","vi":"Về bến cân cá được mấy ký?","parts":["Về bến ",["weigh","cân",2]," cá được mấy ",["kilogram","ký",3],"?"]},{"en":"Write the record in the notebook, then release the fish into the lake.","vi":"Ghi kỷ lục vào sổ rồi thả cá về hồ.","parts":["Ghi ",["record","kỷ lục",3]," vào sổ rồi ",["release","thả",3]," cá về hồ."]}]},{"n":6,"title":"Mặt trời ló núi","minutes":5,"optional":false,"goal":"Cơ hội gặp Cá Hồi Hoàng Gia cho ai có cần vàng.","beats":["Nắng đầu tiên chạm mặt hồ, cá hồi lấp lánh bên dưới.","Cá Cực hiếm cần 3 câu đúng liên tiếp, câu cuối khó nhất."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Danh hiệu \"Ngư Phủ Bình Minh\"; người bắt cá to nhất là MVP.","vocab":["sunrise","legend","rare","shine"],"assets":["fish_king_salmon","fish_rod","hdri_noon","anim_pull_fish","anim_cheer"],"subtitles":[{"en":"At sunrise you may meet the legend, the Royal Salmon.","vi":"Bình minh lên, có thể gặp huyền thoại Cá Hồi Hoàng Gia.","parts":[["Sunrise","Bình minh",3]," lên, có thể gặp ",["legend","huyền thoại",3]," Cá Hồi Hoàng Gia."]},{"en":"This rare fish shines like gold.","vi":"Cá hiếm này lấp lánh như vàng.","parts":["Cá ",["rare","hiếm",3]," này ",["shine","lấp lánh",2]," như vàng."]}]},{"n":7,"title":"Chặng phụ: Cá trê dưới bến","minutes":5,"optional":true,"goal":"Kéo dài: câu cá trê lẩn dưới bến gỗ.","beats":["Cá trê chỉ cắn mồi giun sát đáy."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["catfish","under","bottom"],"assets":["fish_walking_catfish","river_dock"],"subtitles":[{"en":"Catfish lie under the wooden dock, near the bottom.","vi":"Cá trê nằm dưới bến gỗ, sát đáy.","parts":["Cá ",["catfish","trê",3]," nằm ",["under","dưới",1]," bến gỗ, sát ",["bottom","đáy",3],"."]}]},{"n":8,"title":"Chặng phụ: Sổ tay loài cá","minutes":5,"optional":true,"goal":"Viết một câu mô tả mỗi loài cá đã bắt.","beats":["Sổ tay in ra gửi phụ huynh."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết ngắn, không tính thua.","reward":"Huy hiệu \"Nhà Sinh Vật Nhí\".","vocab":["scale","fin","color","long"],"assets":["fish_record_board"],"subtitles":[{"en":"This fish has scales and very long fins.","vi":"Cá này có vảy và vây thật dài.","parts":["Cá này có ",["scale","vảy",3]," và ",["fin","vây",3]," thật ",["long","dài",1],"."]}]}],{},["anim_cast","anim_cheer","anim_fishing_idle","anim_pull_fish","fish_bait","fish_basket","fish_boat_chair","fish_bobber","fish_box","fish_bucket","fish_carp","fish_climbing_perch","fish_cod","fish_crucian","fish_grass_carp","fish_hook","fish_king_salmon","fish_net","fish_record_board","fish_reel","fish_rod","fish_rod_holder","fish_rod_wood","fish_scale","fish_snakehead","fish_tackle_box","fish_tilapia","fish_walking_catfish","hdri_dawn","hdri_noon","kayak_lifejacket","river_boat_aluminium","river_boat_row","river_buoy","river_dock","river_rock_large"]],["fish-02",2,"Giải Câu Cá Mùa Hè Bến Gỗ","Video bến cầu gỗ đưa ra nước; file: tính điểm theo kích thước và độ hiếm.","Trại tổ chức Giải Câu Cá Mùa Hè, phát thanh viên vui tính Bé Bự bình luận trực tiếp qua loa. Mỗi thuyền có 30 phút qua ba vòng: vòng loại ở bến, vòng bán kết giữa sông, vòng chung kết ở khúc sâu. Luật giải rất rõ: điểm theo cân nặng và độ hiếm, thả cá lại sau khi cân, và thuyền nào câu được loài mới sẽ có điểm thưởng. Giữa giải, đội vô địch năm ngoái của Captain Ray tuyên bố sẽ bảo vệ ngôi vương. Chung kết là cuộc săn cá lăng, loài cá hiếm của khúc sông sâu, và ai bắt được sẽ được khắc tên lên cúp gỗ.","Bến gỗ dài đưa ra sông, cờ giải đấu tung bay, bảng điểm lớn trên bờ, khán giả cổ vũ. Nắng sáng rực rỡ, nước sông xanh trong, gió nhẹ. Phao cứu sinh ngăn làn thi và thuyền chèo của ban tổ chức neo cạnh bến. Năm cần câu thi đấu bày trên giá ở bến, người dẫn chương trình chờ khai mạc.",[{"n":1,"title":"Khai mạc","minutes":5,"optional":false,"goal":"Đăng ký thuyền, nhận số áo, chọn cần và mồi xuất phát.","beats":["Bé Bự giới thiệu từng thuyền.","Mỗi câu đúng chọn thêm một món đồ nghề.","Năm cần câu thi đấu bày ra, mỗi đội bốc thăm một cần: nối đúng tên bộ phận trên cần để chọn.","Giá cần câu của ban tổ chức dựng ở bến: mỗi đội chọn đúng cần trước khi khai mạc."],"question_hook":"Câu hỏi trên bảng đăng ký.","reward":"Bộ đồ nghề xuất phát.","vocab":["contest","team","start","number","rod","lucky draw","fishing rod"],"assets":["river_dock","river_sign","fish_tackle_box","fish_rod","camp_bunting","rod_cand_1","rod_cand_2","rod_cand_3","rod_cand_4","rod_cand_5","char_female_b","fish_rod_bundle"],"subtitles":[{"en":"The contest opens: every team gets a number.","vi":"Khai mạc cuộc thi: mỗi đội nhận một số.","parts":["Khai mạc ",["contest","cuộc thi",2],": mỗi ",["team","đội",1]," nhận một ",["number","số",1],"."]},{"en":"Draw your lucky number and start!","vi":"Bốc thăm may mắn rồi xuất phát!","parts":["Bốc thăm may mắn rồi ",["start","xuất phát",0],"!"]}]},{"n":2,"title":"Vòng loại ở bến","minutes":5,"optional":false,"goal":"Câu cá thường ở bến, đạt 300 điểm để vào vòng sau.","beats":["Cá rô phi, cá chép, cá diếc nhiều.","Bảng điểm cập nhật trực tiếp.","Phao ngăn làn: thuyền nào vượt phao khi chưa trả lời đúng bị trừ điểm.","Cá rô biển ở vòng loại cắn mồi: đọc đúng tên mồi để quăng trúng.","Bến nổi trên thùng phuy xanh là nơi xếp hàng vòng loại: đọc đúng luật thi trước khi bước lên."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Vé bán kết.","vocab":["qualify","points","score","catch","lane","lifebuoy","bass","qualifying","floating dock","rope"],"assets":["fish_tilapia","fish_carp","fish_crucian","fish_record_board","river_buoy","fish_bass","fish_floating_dock"],"subtitles":[{"en":"Score three hundred points to qualify.","vi":"Đạt ba trăm điểm để vào vòng sau.","parts":["Đạt ba trăm ",["points","điểm",2]," để ",["qualify","vào vòng sau",3],"."]},{"en":"Every fish you catch adds to your score.","vi":"Mỗi con cá em bắt là thêm điểm.","parts":["Mỗi con cá em ",["catch","bắt",1]," là thêm ",["score","điểm",2],"."]}]},{"n":3,"title":"Bán kết giữa sông","minutes":5,"optional":false,"goal":"Chèo ra giữa sông, săn cá basa và cá tra.","beats":["Dòng chảy đẩy thuyền: câu đúng giữ thuyền đứng yên.","Nâng cần sợi thủy tinh sau 3 câu đúng.","Thuyền trọng tài đi giữa sông chấm cá bán kết.","Cá mè bạc xuất hiện ở bán kết: nhìn màu vảy để đoán đúng tên.","Cần sợi thủy tinh của vòng bán kết: mỗi câu đúng giúp đổi đúng mồi."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cần sợi thủy tinh, vé chung kết.","vocab":["current","middle","basa","steady","referee boat","net","silver carp","semi-final","fiberglass rod","reel"],"assets":["fish_basa","fish_tra","river_boat_aluminium","river_buoy","river_boat_row","fish_silver_carp","fish_rod_fiberglass"],"subtitles":[{"en":"In the middle of the river the current is stronger, so keep steady.","vi":"Ra giữa sông, dòng chảy mạnh hơn, hãy giữ vững.","parts":["Ra giữa sông, ",["current","dòng chảy",2]," mạnh hơn, hãy giữ ",["steady","vững",3],"."]},{"en":"Basa and silver carp swim around the referee boat.","vi":"Cá basa và cá tra bơi quanh thuyền trọng tài.","parts":["Cá basa và cá tra bơi quanh thuyền ",["referee","trọng tài",4],"."]}]},{"n":4,"title":"Thách đấu Captain Ray","minutes":5,"optional":false,"goal":"Đối đầu trực tiếp với thuyền vô địch năm ngoái (thuyền máy điều khiển).","beats":["Ai bắt nhiều điểm hơn trong 5 phút thắng.","Captain Ray câu nhanh theo mức độ khó của lớp.","Captain Ray thách bằng cần carbon đen: đọc đúng các bộ phận của cần để nhận thách đấu."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Mỗi câu đúng trước Captain Ray cướp được một con cá khỏi lưỡi của ông.","reward":"Cần carbon.","vocab":["challenge","faster","beat","champion","carbon rod"],"assets":["fish_snakehead","fish_rainbow_trout","river_boat_aluminium","fish_rod_carbon"],"subtitles":[{"en":"The champion's boat asks: can you beat me?","vi":"Thuyền vô địch hỏi: em có thể đánh bại tôi không?","parts":["Thuyền vô địch hỏi: em có thể ",["beat","đánh bại",2]," tôi không?"]},{"en":"This is a big challenge against the champion.","vi":"Đây là một thử thách lớn với nhà vô địch.","parts":["Đây là một ",["challenge","thử thách",3]," lớn với ",["champion","nhà vô địch",2],"."]}]},{"n":5,"title":"Chung kết khúc sâu","minutes":5,"optional":false,"goal":"Săn cá lăng ở khúc sông sâu.","beats":["Cá lăng hiếm, kéo rất mạnh.","Cả thuyền cùng trả lời để giữ dây.","Cá chung kết được đặt trong giỏ đan trước bảng điểm."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Cá hiếm cần 2 câu đúng liên tiếp.","reward":"Cá lăng vào bảng kỷ lục.","vocab":["final","rare","deep","hold","basket","record"],"assets":["fish_hemibagrus","fish_net","fish_rod","anim_pull_fish","fish_basket"],"subtitles":[{"en":"The final is at the deep part of the river: the final begins!","vi":"Chung kết ở khúc sông sâu: chung kết bắt đầu!","parts":["Chung kết ở khúc sông ",["deep","sâu",1],": ",["final","chung kết",2]," bắt đầu!"]},{"en":"The catfish is rare, so hold your rod tight!","vi":"Cá lăng hiếm, giữ chặt cần nhé!","parts":["Cá lăng ",["rare","hiếm",3],", ",["hold","giữ",1]," chặt cần nhé!"]}]},{"n":6,"title":"Lễ trao cúp","minutes":5,"optional":false,"goal":"Cân cá cuối, công bố thuyền vô địch và MVP.","beats":["Tên người thắng khắc lên cúp gỗ.","Cá được thả lại sông.","Chiếc cần vàng là phần thưởng của nhà vô địch, đặt cạnh chiếc cúp."],"question_hook":"Câu hỏi trên bục trao giải (phỏng vấn ngắn).","reward":"Cúp gỗ + danh hiệu \"Vua Bến Gỗ\".","vocab":["winner","trophy","congratulations","release","gold rod"],"assets":["fish_scale","fish_record_board","river_dock","anim_cheer","fish_rod_gold"],"subtitles":[{"en":"The trophy ceremony for the winner.","vi":"Lễ trao cúp cho người thắng.","parts":["Lễ trao ",["trophy","cúp",3]," cho ",["winner","người thắng",2],"."]},{"en":"Congratulations to the whole team and the MVP!","vi":"Chúc mừng cả đội và MVP!","parts":[["Congratulations","Chúc mừng",3]," cả đội và MVP!"]}]},{"n":7,"title":"Chặng phụ: Giải phụ cá nhỏ nhất","minutes":5,"optional":true,"goal":"Kéo dài: giải vui cho con cá nhỏ nhất.","beats":["Cá nhỏ nhất cũng được thưởng."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["small","tiny","funny"],"assets":["fish_climbing_perch"],"subtitles":[{"en":"A fun prize for the smallest fish: so funny.","vi":"Giải vui cho con cá nhỏ nhất: thật buồn cười.","parts":["Giải vui cho con cá ",["small","nhỏ",1]," nhất: thật ",["funny","buồn cười",2],"."]}]},{"n":8,"title":"Chặng phụ: Phỏng vấn nhà vô địch","minutes":5,"optional":true,"goal":"Mỗi thuyền trả lời phỏng vấn tiếng Anh của Bé Bự.","beats":["Câu trả lời hay phát lại trên loa."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu nói/viết ngắn, không tính thua.","reward":"Huy hiệu \"Ngôi Sao Giải Đấu\".","vocab":["proud","teamwork","next year"],"assets":["river_sign"],"subtitles":[{"en":"We are proud thanks to teamwork; see you next year.","vi":"Chúng em tự hào nhờ tinh thần đồng đội, hẹn năm sau.","parts":["Chúng em ",["proud","tự hào",2]," nhờ ",["teamwork","tinh thần đồng đội",4],", hẹn ",["next year","năm sau",3],"."]}]}],{"note":"Captain Ray là thuyền máy do máy chủ điều khiển, độ khó theo bậc của lớp."},["anim_cheer","anim_pull_fish","camp_bunting","char_female_b","fish_basa","fish_basket","fish_bass","fish_carp","fish_climbing_perch","fish_crucian","fish_floating_dock","fish_hemibagrus","fish_net","fish_rainbow_trout","fish_record_board","fish_rod","fish_rod_bundle","fish_rod_carbon","fish_rod_fiberglass","fish_rod_gold","fish_scale","fish_silver_carp","fish_snakehead","fish_tackle_box","fish_tilapia","fish_tra","river_boat_aluminium","river_boat_row","river_buoy","river_dock","river_sign","rod_cand_1","rod_cand_2","rod_cand_3","rod_cand_4","rod_cand_5"]],["fish-03",3,"Chân Thác Và Cá Lăng Sông Sâu","File: đoạn sông ngọc chảy qua chân núi; video nước trong và vách đá.","Thầy Quang, huấn luyện viên câu cá thể thao, đưa nhóm câu giỏi nhất trại lên chân thác lớn. Ở đây nước chảy mạnh, cá khỏe, chỉ người giữ được thanh căng dây thật vững mới thắng được. Thầy giao một thử thách: bắt đủ ba loài cá sông sâu (cá lăng, cá nheo, cá chình) để được vào \"Câu lạc bộ Chân Thác\". Nhưng dòng nước thay đổi theo giờ, và thuyền phải di chuyển giữa ba vũng nước khác nhau theo bản đồ dòng chảy. Cuối buổi, cả nhóm sẽ thả một con cá lăng thật lớn trở lại vũng sâu, như lời hứa giữ gìn dòng sông.","Khúc sông dưới chân thác lớn, nước xoáy trắng bọt rồi chảy chậm thành vùng sâu xanh thẫm. Vách đá cao hai bên, chim én bay quanh thác, bụi nước lấp lánh. Thung lũng sông nhìn từ trên cao làm bản đồ dòng chảy; thác cao đổ xuống vũng xanh, bọt trắng nổi đầy.",[{"n":1,"title":"Bản đồ dòng chảy","minutes":5,"optional":false,"goal":"Đọc bản đồ dòng chảy, chọn vũng nước đầu tiên.","beats":["Ba vũng: Vũng Bọt, Vũng Xanh, Vũng Đá.","Chọn sai thì nước xoáy đẩy thuyền ra.","Bản đồ nổi của thung lũng sông: ghim ba vũng cá vào đúng chỗ."],"question_hook":"Câu hỏi trên bản đồ dòng chảy.","reward":"Vị trí neo an toàn.","vocab":["current","fast","slow","pool","map","waterfall"],"assets":["surv_map","river_boat_aluminium","water_foam","river_cliff","mini_ganga_valley","river_waterfall"],"subtitles":[{"en":"Read the current map: where is it fast and where is it slow?","vi":"Đọc bản đồ dòng chảy: chỗ nào nhanh, chỗ nào chậm?","parts":["Đọc bản đồ ",["current","dòng chảy",2],": chỗ nào ",["fast","nhanh",1],", chỗ nào ",["slow","chậm",1],"?"]},{"en":"Pick a pool near the waterfall.","vi":"Chọn một vũng nước gần thác.","parts":["Chọn một ",["pool","vũng",3]," nước gần ",["waterfall","thác",2],"."]}]},{"n":2,"title":"Neo thuyền trong nước xiết","minutes":5,"optional":false,"goal":"Thả neo và giữ thuyền ổn định.","beats":["Thanh cân bằng thuyền: câu đúng giữ thuyền không xoay.","Chân thác nước xiết: thả neo đúng chỗ thì thuyền không trôi."],"question_hook":"Câu hỏi trên sợi dây neo; đúng thì neo bám đá.","reward":"Thuyền đứng vững.","vocab":["anchor","stay","balance","rope","rapids"],"assets":["camp_rope","river_rock_large","river_buoy","river_waterfall_pool"],"subtitles":[{"en":"Drop the anchor so the boat stays still in the rapids.","vi":"Thả neo để thuyền đứng yên giữa nước xiết.","parts":["Thả ",["anchor","neo",3]," để thuyền ",["stay","đứng yên",2]," giữa nước xiết."]},{"en":"Keep your balance and do not stand up!","vi":"Giữ thăng bằng nhé, đừng đứng dậy!","parts":["Giữ ",["balance","thăng bằng",3]," nhé, đừng đứng dậy!"]}]},{"n":3,"title":"Vũng Bọt: cá nheo","minutes":5,"optional":false,"goal":"Câu cá nheo trong vũng nước trắng bọt.","beats":["Cá nheo kéo ngang, thanh căng dây lắc trái phải.","Vũng Bọt: bong bóng nổi lên là dấu cá nheo ở dưới."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cá nheo + cần carbon.","vocab":["pull","side","strong","whiskers","foam","bubble"],"assets":["fish_sheatfish","fish_rod","anim_pull_fish","fx_bubbles"],"subtitles":[{"en":"In the white foam pool, the catfish pulls very hard.","vi":"Trong vũng bọt trắng, cá nheo kéo rất mạnh.","parts":["Trong vũng ",["foam","bọt",3]," trắng, cá nheo ",["pull","kéo",1]," rất mạnh."]},{"en":"The catfish has long whiskers and is really strong.","vi":"Cá nheo có râu dài thật khỏe.","parts":["Cá nheo có ",["whiskers","râu",4]," dài thật ",["strong","khỏe",1],"."]}]},{"n":4,"title":"Vũng Xanh: cá lăng","minutes":5,"optional":false,"goal":"Câu cá lăng trong vùng sâu xanh thẫm.","beats":["Cá lăng hiếm, cần 2 câu đúng liên tiếp.","Cá lăng nhiều màu chỉ ngoi lên ở Vũng Xanh."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cá lăng.","vocab":["deep","patient","rare","wait","hemibagrus","deep pool"],"assets":["fish_hemibagrus","fish_bait","water_normal"],"subtitles":[{"en":"The blue pool is very deep, so wait a long time.","vi":"Vũng xanh rất sâu, hãy chờ thật lâu.","parts":["Vũng xanh rất ",["deep","sâu",1],", hãy ",["wait","chờ",1]," thật lâu."]},{"en":"The rare catfish only bites when you are patient.","vi":"Cá lăng hiếm chỉ cắn khi em kiên nhẫn.","parts":["Cá lăng ",["rare","hiếm",3]," chỉ cắn khi em ",["patient","kiên nhẫn",3],"."]}]},{"n":5,"title":"Vũng Đá: cá chình","minutes":5,"optional":false,"goal":"Câu cá chình ẩn trong khe đá.","beats":["Cá chình chui vào khe: phải kéo đúng lúc."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn. Câu dạng sắp xếp: xếp đúng các bước kéo cá ra khỏi khe.","reward":"Cá chình.","vocab":["eel","hide","rock","slippery"],"assets":["fish_eel","river_rock_medium","fish_net"],"subtitles":[{"en":"The eel hides in a rock crack.","vi":"Cá chình ẩn trong khe đá.","parts":["Cá ",["eel","chình",3]," ",["hide","ẩn",2]," trong khe ",["rock","đá",0],"."]},{"en":"Its body is slippery, so be careful it does not slip away!","vi":"Thân nó trơn, cẩn thận kẻo tuột!","parts":["Thân nó ",["slippery","trơn",3],", cẩn thận kẻo tuột!"]}]},{"n":6,"title":"Câu lạc bộ Chân Thác","minutes":5,"optional":false,"goal":"Đủ ba loài: vào câu lạc bộ, thả cá lăng lớn về vũng sâu.","beats":["Lễ thả cá dưới cầu vồng thác.","MVP: người có tổng cân cao nhất."],"question_hook":"Câu lời hứa bảo vệ dòng sông (chọn câu đúng ngữ pháp).","reward":"Huy hiệu \"Câu Lạc Bộ Chân Thác\".","vocab":["protect","promise","river","nature"],"assets":["fish_hemibagrus","hdri_noon","anim_cheer"],"subtitles":[{"en":"You join the club to protect the river.","vi":"Em vào câu lạc bộ để bảo vệ dòng sông.","parts":["Em vào câu lạc bộ để ",["protect","bảo vệ",3]," ",["river","dòng sông",1],"."]},{"en":"I promise to protect nature.","vi":"Em hứa bảo vệ thiên nhiên.","parts":["Em ",["promise","hứa",2]," bảo vệ thiên ",["nature","nhiên",3],"."]}]},{"n":7,"title":"Chặng phụ: Cá hồi vân","minutes":5,"optional":true,"goal":"Kéo dài: cá hồi vân bơi ngược thác.","beats":["Cá nhảy khỏi mặt nước."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["jump","upstream"],"assets":["fish_rainbow_trout"],"subtitles":[{"en":"Rainbow trout jump upstream over the falls.","vi":"Cá hồi vân nhảy ngược dòng qua thác.","parts":["Cá hồi vân ",["jump","nhảy",1]," ",["upstream","ngược dòng",4]," qua thác."]}]},{"n":8,"title":"Chặng phụ: Biển báo bảo vệ","minutes":5,"optional":true,"goal":"Viết biển báo tiếng Anh bảo vệ dòng sông.","beats":["Biển báo cắm ở chân thác."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết, không tính thua.","reward":"Huy hiệu \"Người Giữ Sông\".","vocab":["do not","please","keep clean"],"assets":["river_sign"],"subtitles":[{"en":"Do not litter; please keep the river clean.","vi":"Đừng xả rác, xin hãy giữ sạch dòng sông.","parts":[["Do not","Đừng",1]," xả rác, ",["please","xin hãy",1]," ",["keep clean","giữ sạch",2]," dòng sông."]}]}],{"note":"Ba vũng nước = ba khu; thuyền xoay vòng khu mỗi 5 phút để lớp đông không chen một vũng."},["anim_cheer","anim_pull_fish","camp_rope","fish_bait","fish_eel","fish_hemibagrus","fish_net","fish_rainbow_trout","fish_rod","fish_sheatfish","fx_bubbles","hdri_noon","mini_ganga_valley","river_boat_aluminium","river_buoy","river_cliff","river_rock_large","river_rock_medium","river_sign","river_waterfall","river_waterfall_pool","surv_map","water_foam","water_normal"]],["fish-04",4,"Đêm Trăng Câu Cá Tra","Video hồ và rừng thông; ý tưởng câu cá đêm với đèn lồng, phao phát sáng.","Đêm trăng tròn, chú Tâm mở chuyến \"Câu đêm Trăng Rằm\" vì cá tra và cá basa chỉ ăn mồi nhiều vào ban đêm. Mỗi thuyền được phát một đèn lồng và những chiếc phao phát sáng, cá cắn câu thì phao lóe sáng. Nhưng giữa đêm, một đám sương dày trôi qua che mất trăng, đèn lồng của vài thuyền tắt. Các thuyền phải giúp nhau thắp lại đèn, đọc dấu sao để tìm đường về các bãi cá. Gần nửa đêm, mặt sông sáng lên vì đàn cá tra lớn bơi qua, đó là lúc tranh tài cuối cùng.","Sông rộng về đêm, trăng tròn, đèn lồng treo trên mũi thuyền, phao phát sáng xanh lá trên mặt nước. Tiếng ếch nhái, gió mát, đom đóm ven bờ.",[{"n":1,"title":"Thắp đèn mũi thuyền","minutes":5,"optional":false,"goal":"Thắp đèn lồng, buộc phao phát sáng.","beats":["Mỗi câu đúng thắp sáng một phao.","Đèn trụ bến sáng ấm: thắp đèn mũi thuyền bằng cách đọc đúng tên từng bộ phận của đèn."],"question_hook":"Câu hỏi trên chiếc đèn lồng.","reward":"Đèn + phao sáng.","vocab":["lantern","glow","moon","night","lamp"],"assets":["camp_lantern","fish_bobber","river_boat_aluminium","hdri_night","fish_dock_lamp"],"subtitles":[{"en":"Light the lantern at the bow under the moon.","vi":"Thắp đèn lồng ở mũi thuyền dưới trăng.","parts":["Thắp ",["lantern","đèn lồng",2]," ở mũi thuyền dưới ",["moon","trăng",0],"."]},{"en":"The float glows pale green in the night.","vi":"Phao phát sáng xanh nhạt trong đêm.","parts":["Phao ",["glow","phát sáng",2]," xanh nhạt trong ",["night","đêm",0],"."]}]},{"n":2,"title":"Cá đêm đầu tiên","minutes":5,"optional":false,"goal":"Câu cá basa dưới ánh trăng.","beats":["Phao lóe sáng khi cá cắn.","Một con cá lạ ánh bạc chưa ai biết tên: cả đội đoán đặc điểm để đặt tên cho nó."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cá basa.","vocab":["bite","flash","quiet","basa","mystery","night fish"],"assets":["fish_basa","fish_reel","anim_cast","fish_unknown"],"subtitles":[{"en":"A flash on the water: a fish is biting!","vi":"Ánh chớp trên mặt nước: có cá cắn!","parts":["Ánh ",["flash","chớp",3]," trên mặt nước: có cá ",["bite","cắn",2],"!"]},{"en":"Stay quiet so the basa does not get startled.","vi":"Hãy im lặng để cá basa không giật mình.","parts":["Hãy ",["quiet","im lặng",2]," để cá basa không giật mình."]}]},{"n":3,"title":"Mồi đêm","minutes":5,"optional":false,"goal":"Đổi mồi phù hợp cá đêm (mồi tôm, mồi cám).","beats":["Nâng cần sau 3 câu đúng.","Thợ câu ngồi chờ dưới trăng, tay giữ cần thật yên: đọc đúng tên động tác trước khi nâng cần."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cần sợi thủy tinh + mồi tôm.","vocab":["shrimp","smell","choose","bobber","wait"],"assets":["fish_bait","fish_tackle_box","anim_fishing_idle"],"subtitles":[{"en":"Shrimp bait has a smell fish like.","vi":"Mồi tôm có mùi cá thích.","parts":["Mồi ",["shrimp","tôm",2]," có ",["smell","mùi",2]," cá thích."]},{"en":"You must choose the right bait for night fish.","vi":"Em phải chọn mồi đúng cho cá đêm.","parts":["Em phải ",["choose","chọn",2]," mồi đúng cho cá đêm."]}]},{"n":4,"title":"Sương che trăng","minutes":5,"optional":false,"goal":"Đèn tắt: giúp thuyền bên cạnh thắp lại, dựa vào sao tìm bãi cá.","beats":["Câu đúng của thuyền này thắp đèn cho thuyền kia.","Sao Bắc Đẩu chỉ hướng bãi cá."],"question_hook":"Câu hỏi trên ngọn đèn của thuyền bạn; hợp câu hướng (north, east).","reward":"Cả lớp sáng đèn lại.","vocab":["fog","help","star","direction"],"assets":["camp_lantern","hdri_night","surv_compass"],"subtitles":[{"en":"Fog covers the moon and all the lights go out!","vi":"Sương che trăng, đèn tắt hết!","parts":[["Fog","Sương",2]," che trăng, đèn tắt hết!"]},{"en":"Look at the stars to find the right direction.","vi":"Nhìn sao để tìm đúng hướng.","parts":["Nhìn ",["star","sao",0]," để tìm đúng ",["direction","hướng",3],"."]}]},{"n":5,"title":"Cá trê và cá lóc ven bờ","minutes":5,"optional":false,"goal":"Câu sát bờ lau, cá trê và cá lóc ra kiếm ăn.","beats":["Lau sậy rung khi cá đến."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Cần carbon.","vocab":["shore","reed","snakehead","catfish"],"assets":["fish_walking_catfish","fish_snakehead","river_reed"],"subtitles":[{"en":"Catfish and snakehead come out to feed along the bank.","vi":"Cá trê và cá lóc ra kiếm ăn ven bờ.","parts":["Cá ",["catfish","trê",3]," và cá ",["snakehead","lóc",4]," ra kiếm ăn ven bờ."]},{"en":"Fish close to the shore, where reeds grow thick.","vi":"Câu sát bờ, nơi lau mọc dày.","parts":["Câu sát ",["shore","bờ",2],", nơi ",["reed","lau",2]," mọc dày."]}]},{"n":6,"title":"Đàn cá tra nửa đêm","minutes":5,"optional":false,"goal":"Mặt sông sáng lên, tranh tài câu cá tra lớn.","beats":["Cá tra lớn cần 2 câu đúng liên tiếp.","MVP: cá nặng nhất đêm."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Danh hiệu \"Ngư Phủ Trăng Rằm\".","vocab":["midnight","big","school of fish","win"],"assets":["fish_tra","fish_net","anim_pull_fish","anim_cheer"],"subtitles":[{"en":"At midnight, the river surface lights up.","vi":"Lúc nửa đêm, mặt sông sáng lên.","parts":["Lúc ",["midnight","nửa đêm",3],", mặt sông sáng lên."]},{"en":"A big school of fish swims by: who wins?","vi":"Một đàn cá lớn bơi tới, ai thắng?","parts":["Một ",["school of fish","đàn cá",3]," lớn bơi tới, ai ",["win","thắng",1],"?"]}]},{"n":7,"title":"Chặng phụ: Cá chình đêm","minutes":5,"optional":true,"goal":"Kéo dài: cá chình ra khỏi hang ban đêm.","beats":["Rất trơn, khó giữ."],"question_hook":"Thanh căng dây như các chặng chính: kéo cần về đúng vùng đáp án. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["eel","slippery"],"assets":["fish_eel"],"subtitles":[{"en":"The slippery eel leaves its hole at night.","vi":"Cá chình trơn ra khỏi hang ban đêm.","parts":["Cá ",["eel","chình",3]," ",["slippery","trơn",3]," ra khỏi hang ban đêm."]}]},{"n":8,"title":"Chặng phụ: Thơ trăng","minutes":5,"optional":true,"goal":"Viết hai câu thơ tiếng Anh về trăng và sông.","beats":["Thơ hay đọc trên loa trại."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình vào Sổ Câu Cá. Câu viết, không tính thua.","reward":"Huy hiệu \"Thi Sĩ Sông Trăng\".","vocab":["moonlight","silver","calm"],"assets":["hdri_night"],"subtitles":[{"en":"Two lines of poetry about silver moonlight and the calm river.","vi":"Hai câu thơ về ánh trăng bạc và dòng sông êm.","parts":["Hai câu thơ về ",["moonlight","ánh trăng",3]," ",["silver","bạc",2]," và dòng sông ",["calm","êm",2],"."]}]}],{},["anim_cast","anim_cheer","anim_fishing_idle","anim_pull_fish","camp_lantern","fish_bait","fish_basa","fish_bobber","fish_dock_lamp","fish_eel","fish_net","fish_reel","fish_snakehead","fish_tackle_box","fish_tra","fish_unknown","fish_walking_catfish","hdri_night","river_boat_aluminium","river_reed","surv_compass"]],["fish-05",5,"Truyền Thuyết Vua Cá Hồi","File: Cá Hồi Hoàng Gia (cá MVP), nâng cấp cần và mồi để săn cá khổng lồ; video câu cá trên thuyền.","Ông Chài Tư giữ một cuốn sổ cũ ghi về Vua Cá Hồi, con cá hồi hoàng gia khổng lồ chưa ai bắt được trong 30 năm. Sổ chép ba manh mối bằng tiếng Anh từ một nhà thám hiểm xưa: loại mồi Vua Cá thích, nơi nó nghỉ trưa và giờ nó ra khỏi hang. Mỗi thuyền phải đi qua ba khúc sông, bắt các loài cá chỉ đường và giải từng manh mối để mở khóa cần vàng. Nhưng một thuyền đối thủ do Bà Mũi Nhọn dẫn đầu cũng đang săn Vua Cá, muốn đem nó lên chợ. Lúc hoàng hôn, Vua Cá ra khỏi hang; thuyền bắt được sẽ cân, chụp ảnh và thả nó về sông như lời hứa với ông Chài Tư.","Ba khúc sông nối nhau: bến gỗ làng chài, hồ rộng giữa núi và cửa hang nơi sông chảy ra từ lòng núi. Từ trưa đến hoàng hôn, nắng vàng rồi đỏ rực. Trong cuốn sổ ông Chài Tư có bản đồ nổi của lưu vực sông.",[{"n":1,"title":"Cuốn sổ của ông Chài Tư","minutes":5,"optional":false,"goal":"Đọc trang đầu cuốn sổ, nhận nhiệm vụ.","beats":["Phim ngắn: bóng cá khổng lồ dưới nước.","Mỗi câu đúng mở một trang sổ.","Bản đồ nổi lưu vực sông chỉ ba khúc sông; chạm đúng tên khúc sông thì sổ mở trang."],"question_hook":"Cuốn sổ cũ; câu đọc hiểu ngắn mở từng trang.","reward":"Manh mối 1: loại mồi.","vocab":["legend","giant","clue","old","river basin","map"],"assets":["surv_letter","river_dock","river_cabin","fish_king_salmon","mini_indus_basin"],"subtitles":[{"en":"The old notebook tells a legend about a giant fish.","vi":"Cuốn sổ cũ ghi về một huyền thoại: con cá khổng lồ.","parts":["Cuốn sổ cũ ghi về một ",["legend","huyền thoại",3],": con cá ",["giant","khổng lồ",2],"."]},{"en":"Every page is an old clue.","vi":"Mỗi trang là một manh mối cũ.","parts":["Mỗi trang là một ",["clue","manh mối",3]," ",["old","cũ",1],"."]}]},{"n":2,"title":"Bến làng chài","minutes":5,"optional":false,"goal":"Bắt cá rô phi, cá trắm để đổi lấy mồi ruồi đặc biệt.","beats":["Ngư dân làng đổi mồi lấy cá.","Thuyền chèo và giỏ đan của làng chài nằm sẵn ở bến.","Một người lạ đi bộ qua bến làng chài, hỏi đường tới hồ giữa núi."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Mồi ruồi đặc biệt.","vocab":["trade","fly","village","rowboat","basket","stranger"],"assets":["fish_tilapia","fish_grass_carp","fish_bait","fish_bucket","river_boat_row","fish_basket","char_wanderer"],"subtitles":[{"en":"At the fishing village dock, trade fish for special fly bait.","vi":"Ở bến làng chài, em đổi cá lấy mồi ruồi.","parts":["Ở bến làng chài, em ",["trade","đổi",3]," cá lấy mồi ",["fly","ruồi",3],"."]},{"en":"The fishing village folk show you the way.","vi":"Người làng chài chỉ đường cho em.","parts":["Người ",["village","làng",1]," chài chỉ đường cho em."]}]},{"n":3,"title":"Hồ giữa núi","minutes":5,"optional":false,"goal":"Câu cá hồi vân để biết nơi Vua Cá nghỉ trưa (manh mối 2).","beats":["Cá hồi vân bơi về hướng Vua Cá.","Nâng cần carbon sau 3 câu đúng.","Hồ giữa núi nhìn thấy đáy: đá nào, cá nào đọc đúng tên mới thấy."],"question_hook":"Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.","reward":"Manh mối 2 + cần carbon.","vocab":["lake","rest","follow","trout","clear water","rock"],"assets":["fish_rainbow_trout","river_boat_aluminium","hdri_noon","mini_clear_river"],"subtitles":[{"en":"The mountain lake has clear water: the Fish King rests here at noon.","vi":"Hồ giữa núi nước trong: Vua Cá nghỉ trưa ở đây.","parts":["Hồ giữa 